import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { CardComponent } from './card.component';

// ❌ OLD: The component must be declared in a module, and consumers
// must import the module to use it. Extra indirection, and lazy
// loading pulls the whole module (all its declarations) together.
@NgModule({
  declarations: [CardComponent], // ❌ OLD: declaration indirection
  imports: [CommonModule],
  exports: [CardComponent], // ❌ OLD: re-export to make it usable
})
export class CardModule {}

// Usage: imports: [CardModule] in another module, or NgModule-based
// lazy loading via loadChildren.

