fullFile.code:
import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';

// ✅ NEW: The component imports exactly what it needs. No NgModule
// wrapper, direct lazy loading, tree-shakable.
@Component({
  selector: 'app-card',
  imports: [CommonModule], // ✅ NEW: direct dependency declaration
  template: `<p>Card</p>`,
})
export class CardComponent {}

// Lazy route:
// {
//   path: 'card',
//   loadComponent: () => import('./card.component').then((m) => m.CardComponent),
// }

// The compiler builds the dependency graph straight from the imports
// array — no module boundary involved.
